<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;color:#17221f;font-size:10pt}h1,h2{color:#155c4a}.cover{page-break-after:always;padding-top:100px}.finding{page-break-inside:avoid;margin:18px 0}.footer{position:fixed;bottom:-20px;font-size:8pt}table{width:100%;border-collapse:collapse}th,td{border:1px solid #aaa;padding:6px;text-align:left}</style></head><body><div class="footer"><?php echo esc_html($report['branding']['pdf_footer']); ?></div><section class="cover"><?php if($report['branding']['logo_data']):?><img src="<?php echo esc_attr($report['branding']['logo_data']);?>" alt="Acorn Safety Services" style="max-width:180px"><?php endif;?><h1>Health &amp; Safety Healthcheck Report</h1><p>Covering Health &amp; Safety · Fire · Legionella · Asbestos</p><h2><?php echo esc_html($report['meta']['company']);?></h2><p>Self-assessment report · <?php echo esc_html($report['meta']['assessment_date']);?></p><p><?php echo esc_html($report['branding']['phone']);?> · <?php echo esc_html($report['branding']['website']);?></p></section><h1>Executive summary</h1><p><?php echo (int)$report['summary']['priority_count'];?> priority actions · <?php echo (int)$report['summary']['review_count'];?> areas to review · <?php echo (int)$report['summary']['addressed_count'];?> addressed</p><ul><?php foreach($report['pillars']as$pillar):?><li><?php echo esc_html($pillar['label'].': '.ucwords(str_replace('_',' ',$pillar['status'])));?></li><?php endforeach;?></ul><p><?php echo esc_html($report['disclaimer']);?></p><?php foreach(['addressed','review','priority']as$type):?><h2><?php echo esc_html($report['sections'][$type]['label']);?></h2><?php foreach($report[$type]as$item):?><div class="finding"><h3><?php echo esc_html($item['recommendation']['heading']??$item['positive_text']);?></h3><?php if($type==='addressed'):?><p><?php echo esc_html($item['positive_text']);?></p><?php else:?><p><b>What we identified:</b> <?php echo esc_html($item['recommendation']['identified_text']);?></p><p><b>Recommended next step:</b> <?php echo esc_html($item['recommendation']['next_step_text']);?></p><p><b>Why this matters:</b> <?php echo esc_html($item['recommendation']['why_text']);?></p><p><b>What good looks like:</b> <?php echo esc_html($item['recommendation']['good_looks_text']);?></p><?php endif;?></div><?php endforeach;?><?php endforeach;?><h2>Action summary</h2><table><tr><th>Status</th><th>Area</th><th>Action</th></tr><?php foreach($report['action_summary']as$item):?><tr><td><?php echo esc_html($item['finding_status']);?></td><td><?php echo esc_html($item['recommendation']['heading']);?></td><td><?php echo esc_html($item['recommendation']['next_step_text']);?></td></tr><?php endforeach;?></table><h2><?php echo esc_html($report['support']['heading']);?></h2><p>If you do not have the relevant expertise internally, Acorn can assist. <?php echo esc_html($report['support']['cta_label']);?></p></body></html>
